    pub fn new_jsdoc_parameter_or_property_tag(
        &self,
        kind: Kind,
        tag_name: P<Node>,
        name: P<Node>,
        is_bracketed: bool,
        type_expression: Option<P<Node>>,
        is_name_first: bool,
        comment: Option<P<NodeList>>,
    ) -> P<Node> {
        assert!(
            matches!(kind, Kind::JSDocParameterTag | Kind::JSDocPropertyTag),
            "Invalid node kind for JSDocParameterOrPropertyTag"
        );
        self.new_node(
            kind,
            JSDocParameterOrPropertyTag {
                jsdoc_tag_base: JSDocTagBase { tag_name, comment },
                name,
                is_bracketed,
                type_expression,
                is_name_first,
            },
        )
    }

    pub(crate) fn update_jsdoc_parameter_or_property_tag(
        &self,
        node: P<Node>,
        tag_name: P<Node>,
        name: P<Node>,
        is_bracketed: bool,
        type_expression: Option<P<Node>>,
        is_name_first: bool,
        comment: Option<P<NodeList>>,
    ) -> P<Node> {
        let data = node.as_jsdoc_parameter_or_property_tag();
        if tag_name != data.tag_name()
            || name != data.name()
            || is_bracketed != data.is_bracketed()
            || type_expression != data.type_expression()
            || is_name_first != data.is_name_first()
            || comment != data.comment()
        {
            return update_node(
                self.new_jsdoc_parameter_or_property_tag(
                    node.kind(),
                    tag_name,
                    name,
                    is_bracketed,
                    type_expression,
                    is_name_first,
                    comment,
                ),
                node,
                &self.hooks,
            );
        }
        node
    }
